<?php use Hls\Http\View as V; ?><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama</th><th>Cabang</th><th>Gudang</th><th>Satuan</th><th>Stok Fisik</th><th>Dicadangkan</th><th>Tersedia</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): $physical=(float)$r['stock_qty'];$reserved=(float)($r['reserved_qty']??0);$availableQty=$physical-$reserved; ?><tr><td><?= V::escape($r['code']) ?></td><td><?= V::escape($r['name']) ?></td><td><?= V::escape($r['branch_code']) ?></td><td><?= V::escape($r['warehouse_name']??'Belum dialokasikan') ?></td><td><?= V::escape($r['unit_name']) ?></td><td><?= number_format($physical,3,',','.') ?></td><td><?= number_format($reserved,3,',','.') ?></td><td><?= number_format($availableQty,3,',','.') ?></td><td><?= $availableQty>0?'Tersedia':'Habis' ?></td><td><a href="<?= $this->url('/inventory/stock-detail?item_id='.(int)$r['id'].'&branch_id='.(int)$r['branch_id'].'&warehouse_id='.(int)($r['warehouse_id']??0)) ?>">Detail</a></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="10" class="empty-state">Belum ada stok atau master barang dalam cakupan.</td></tr><?php endif ?></tbody></table></div></section>
